interface GetAttachmentSignature {
  /**
   * Retrieves the specified attachment for the specified contact.
   * @returns The requested attachment.
   */
  (
    identifiers: NonNullablePaths<
      GetAttachmentIdentifiers,
      `attachmentId` | `contactId`,
      0
    >
  ): Promise<
    NonNullablePaths<
      ContactAttachment,
      `_id` | `fileName` | `mimeType` | `attachmentType`,
      0
    >
  >;
}

export const onAttachmentCreated = /*#__PURE__*/ EventDefinition(
  'wix.contacts.v4.attachment_created',
  true,
  (event: AttachmentCreatedEnvelope) =>
    renameKeysFromRESTResponseToSDKResponse(
      transformPaths(event, [
        {
          transformFn: transformRESTImageToSDKImage,
          paths: [{ path: 'entity.image' }, { path: 'entity.previewImage' }],
        },
        {
          transformFn: transformRESTDocumentToSDKDocument,
          paths: [{ path: 'entity.document' }],
        },
        {
          transformFn: transformRESTTimestampToSDKTimestamp,
          paths: [{ path: 'metadata.eventTime' }],
        },
      ])
    )
)<AttachmentCreatedEnvelope>();
export const onAttachmentDeleted = /*#__PURE__*/ EventDefinition(
  'wix.contacts.v4.attachment_deleted',
  true,
  (event: AttachmentDeletedEnvelope) =>
    renameKeysFromRESTResponseToSDKResponse(
      transformPaths(event, [
        {
          transformFn: transformRESTImageToSDKImage,
          paths: [
            { path: 'undefined.image' },
            { path: 'undefined.previewImage' },
          ],
        },
        {
          transformFn: transformRESTDocumentToSDKDocument,
          paths: [{ path: 'undefined.document' }],
        },
        {
          transformFn: transformRESTTimestampToSDKTimestamp,
          paths: [{ path: 'metadata.eventTime' }],
        },
      ])
    )
)<AttachmentDeletedEnvelope>();

